import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
import { readFileSync, mkdirSync } from 'node:fs';
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
try {
  const page = await browser.newPage({ viewport: { width: 1100, height: 850 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  const response = await page.goto('http://127.0.0.1:3002', { waitUntil: 'networkidle', timeout: 30000 });
  if (!response?.ok()) throw new Error(`Load failed: ${response?.status()}`);
  const canvas = page.locator('#scene');
  const box = await canvas.boundingBox();
  await page.mouse.move(box.x + 185, box.y + box.height * 446 / 720);
